                            .setColor("BLURPLE")
                            .setThumbnail(message.author.displayAvatarURL)
                            .addField("Pet Name", name)
                            .addField("XP/LVL: ", "0/1");

                        message.channel.send(embed);
                        newDoc.save().catch(err => console.log(err));

